package com.ruoyi.metal.service;
import java.math.BigDecimal;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;
/** Weight conversion breaks piece conservation; real source routes, not reference counts, prove coverage. */
public final class WeightStageProgressService {
 private WeightStageProgressService(){}
 public static boolean hasWeightInput(JdbcTemplate j,long batch){BigDecimal n=j.queryForObject("SELECT COALESCE(SUM(CASE WHEN o.type='PRODUCTION_OUT' THEN l.net_weight WHEN o.type='SEMI_RETURN' THEN -COALESCE(l.processor_net_weight,l.net_weight) ELSE 0 END),0) FROM metal_warehouse_order o JOIN metal_warehouse_order_line l ON l.order_id=o.order_id WHERE o.batch_id=? AND o.status='POSTED' AND l.category='SEMI' AND l.measurement_mode='WEIGHT'",BigDecimal.class,batch);return n!=null&&n.signum()>0;}
 public static boolean hasWeightInput(JdbcTemplate j,Map<String,?> batch){
  if(!MeasurementPolicy.configurable(j,batch))return hasWeightInput(j,SemiFlowService.num(batch.get("batch_id")));
  BigDecimal net=BigDecimal.ZERO;
  for(var line:SemiFlowService.measurementInputs(j,batch))if(InventoryMeasurement.weight(line)){
   BigDecimal weight=SemiFlowService.dec(line.get("processor_net_weight")==null?line.get("net_weight"):line.get("processor_net_weight"));
   net="PRODUCTION_OUT".equals(line.get("type"))?net.add(weight):net.subtract(weight);
  }
  return net.signum()>0;
 }
 public static BigDecimal semiInput(JdbcTemplate j,long batch){return j.queryForObject("SELECT COALESCE(SUM(CASE WHEN o.type='PRODUCTION_OUT' THEN l.net_weight WHEN o.type='SEMI_RETURN' THEN -COALESCE(l.processor_net_weight,l.net_weight) ELSE 0 END),0) FROM metal_warehouse_order o JOIN metal_warehouse_order_line l ON l.order_id=o.order_id WHERE o.batch_id=? AND o.status='POSTED' AND l.category='SEMI'",BigDecimal.class,batch);}
 static boolean qualificationCovered(JdbcTemplate j,long item,long sequence){
  return j.queryForObject("SELECT COUNT(*) FROM metal_work_order_step s JOIN metal_raw_qualification_use q ON q.item_id=s.item_id JOIN metal_warehouse_order_line l ON l.line_id=q.line_id AND l.inventory_id=q.inventory_id JOIN metal_warehouse_order o ON o.order_id=l.order_id JOIN metal_process_batch b ON b.batch_id=o.batch_id AND b.item_id=q.item_id AND b.process_id=q.process_id WHERE s.item_id=? AND s.sequence_no=? AND s.output_stage='RAW' AND s.process_role IN ('ACID_WASH','PREPARATION') AND b.sequence_no>s.sequence_no AND b.processing_policy_version>=2 AND b.process_role='SMELTING' AND b.status='SETTLED' AND o.type='PRODUCTION_OUT' AND o.status='POSTED' AND l.category='RAW' AND l.net_weight>COALESCE((SELECT SUM(r.net_weight) FROM metal_warehouse_order_line r JOIN metal_warehouse_order returned ON returned.order_id=r.order_id WHERE r.source_line_id=l.line_id AND returned.type='RAW_RETURN' AND returned.status='POSTED'),0)",Long.class,item,sequence)>0;
 }
 private static boolean localWeightWork(JdbcTemplate j,long item,long sequence){return j.queryForObject("SELECT COUNT(*) FROM metal_work_order_step s JOIN metal_work_order_item i ON i.item_id=s.item_id JOIN metal_work_order w ON w.work_order_id=i.work_order_id WHERE s.item_id=? AND s.sequence_no=? AND w.processing_policy_version>=3 AND s.measurement_mode='WEIGHT' AND EXISTS(SELECT 1 FROM metal_process_batch local WHERE local.item_id=s.item_id AND local.sequence_no=s.sequence_no AND local.status IN ('OPEN','SETTLED'))",Long.class,item,sequence)>0;}
 static boolean externalCovered(JdbcTemplate j,long item,long sequence){return !localWeightWork(j,item,sequence)&&externalQualification(j,item,sequence);}
 private static boolean externalQualification(JdbcTemplate j,long item,long sequence){return qualificationCovered(j,item,sequence)||j.queryForObject("SELECT COUNT(*) FROM metal_semi_release_use u JOIN metal_warehouse_order_line l ON l.line_id=u.line_id JOIN metal_warehouse_order o ON o.order_id=l.order_id JOIN metal_process_batch b ON b.batch_id=o.batch_id WHERE b.item_id=? AND b.sequence_no>? AND b.status='SETTLED' AND o.status='POSTED' AND EXISTS(SELECT 1 FROM metal_work_order_step conversion WHERE conversion.item_id=b.item_id AND conversion.sequence_no>=? AND conversion.sequence_no<b.sequence_no AND conversion.measurement_mode='WEIGHT') AND l.net_weight>COALESCE((SELECT SUM(r.net_weight) FROM metal_warehouse_order_line r JOIN metal_warehouse_order ro ON ro.order_id=r.order_id WHERE r.source_line_id=l.line_id AND ro.status='POSTED'),0)",Long.class,item,sequence,sequence)>0;}
 static boolean covered(JdbcTemplate j,Map<String,Object> s,SemiFlowService semi){long item=SemiFlowService.num(s.get("item_id")),seq=SemiFlowService.num(s.get("sequence_no"));if(localWeightWork(j,item,seq))return Boolean.TRUE.equals(s.get("weight_stage_closed"))&&j.queryForObject("SELECT COUNT(*) FROM metal_process_batch WHERE item_id=? AND sequence_no=? AND status='SETTLED'",Long.class,item,seq)>0;if(externalQualification(j,item,seq))return true;for(var r:j.queryForList("SELECT u.new_skipped,b.batch_id FROM metal_route_skip_use u JOIN metal_process_batch b ON b.batch_id=u.batch_id JOIN metal_warehouse_order_line l ON l.line_id=u.line_id JOIN metal_warehouse_order o ON o.order_id=l.order_id WHERE u.item_id=? AND b.status='SETTLED' AND o.status='POSTED' AND l.measurement_mode='WEIGHT' AND l.net_weight>COALESCE((SELECT SUM(x.net_weight) FROM metal_warehouse_order_line x JOIN metal_warehouse_order d ON d.order_id=x.order_id WHERE x.source_line_id=l.line_id AND d.status='POSTED'),0)",item)){if(com.alibaba.fastjson2.JSON.parseArray(r.get("new_skipped").toString(),Long.class).contains(seq))return true;}
 if(SemiMeasurementRules.weight(s))return Boolean.TRUE.equals(s.get("weight_stage_closed"))&&j.queryForObject("SELECT COUNT(*) FROM metal_process_batch WHERE item_id=? AND sequence_no=? AND status='SETTLED'",Long.class,item,seq)>0;
 // Earlier pieces converted to powder cannot be equated with the final piece plan.
 if(j.queryForObject("SELECT COUNT(*) FROM metal_work_order_step w WHERE w.item_id=? AND w.sequence_no>? AND w.measurement_mode='WEIGHT' AND w.weight_stage_closed=TRUE AND EXISTS(SELECT 1 FROM metal_process_batch b WHERE b.item_id=w.item_id AND b.process_id=w.process_id AND b.status='SETTLED')",Long.class,item,seq)>0)return true;
 long done=j.queryForObject("SELECT COALESCE(SUM(completed_quantity),0) FROM metal_process_batch WHERE item_id=? AND sequence_no=? AND status='SETTLED'",Long.class,item,seq);return done+semi.credit(item,seq)==SemiFlowService.num(s.get("quantity"));}
}
